// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

library MathLib {
    function triple(uint256 x) external pure returns (uint256) {
        return x * 3;
    }
}

contract Calculator {
    function run(uint256 x) external pure returns (uint256) {
        return MathLib.triple(x);
    }
}
